{
  "status": "SUPPORTED",
  "task_summary": "Identify compatible components, complete fastening at a marked workbench location, and place reusable tool back on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "active_tool",
        "entity_kind": "OBJECT",
        "function": "A reusable instrument used to perform the fastening.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["hand-held tool", "fastener", "mechanical instrument"],
        "required_properties": ["is_manipulable", "rigid_structure"]
      },
      {
        "id": "marked_assembly_site",
        "entity_kind": "FIXED_TARGET",
        "function": "The specific location on the workbench designated for assembly.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["marked surface", "marked point", "assembly location"],
        "required_properties": ["surface_acceptance", "static_position"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "The support plane providing space for the assembly and tool storage.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["desk", "table", "workbench top"],
        "required_properties": ["horizontal_plane", "stable_support"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_001",
        "subject_role": "marked_assembly_site",
        "relation": "is_part_of",
        "object_role": "workbench_surface",
        "required": true
      },
      {
        "id": "relation_002",
        "subject_role": "active_tool",
        "relation": "interacts_at_location",
        "object_role": "marked_assembly_site",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_001",
        "operation": "complete_fastening",
        "source_role": "active_tool",
        "target_role": "marked_assembly_site",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "workbench_surface"
      },
      {
        "id": "op_002",
        "operation": "place_reusable_equipment",
        "source_role": "active_tool",
        "target_role": "workbench_surface",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET"
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "active_tool": [
        {
          "label": "yellow_handled_object",
          "visual_description": "A yellow rigid object held in the robot gripper, resembling a tool or component."
        }
      ],
